#Requires -Version 5.1
<#
.SYNOPSIS
    Self-extracting, password-protected YallaCloud C:\Scripts payload.

.DESCRIPTION
    Windows PowerShell 5.1 CANNOT open a password-protected zip. Expand-Archive
    has no password parameter and neither does System.IO.Compression.ZipFile -
    the encryption is simply not implemented in either. So this file is not a
    zip: it is a script carrying an AES-256-CBC encrypted copy of the payload
    and the few lines of .NET needed to decrypt it. Nothing to install, no
    7-Zip, no WinRAR.

    Crypto: PBKDF2-HMAC-SHA1, 200,000 iterations, 16-byte random salt, to a
    64-byte key - the first 32 bytes are the AES-256 key, the last 32 are a
    separate HMAC-SHA256 key. The MAC is verified BEFORE any decryption is
    attempted, so a wrong password or a tampered file fails cleanly instead of
    handing you corrupt output.

    The password is NOT in this file and never will be. It is supplied at run
    time and travels to you by a different route than this download.

.PARAMETER Destination
    Where to put the Scripts folder. Default C:\ - which lands it at C:\Scripts.

.PARAMETER Password
    The archive password. Omitted, you are prompted for it (masked).

.PARAMETER SaveZipOnly
    Write the decrypted .zip next to this script and stop. Nothing is extracted.

.EXAMPLE
    .\Extract-YcScripts.ps1
    Prompts for the password, extracts to C:\Scripts.

.EXAMPLE
    .\Extract-YcScripts.ps1 -Destination D:\Staging
    Extracts to D:\Staging\Scripts so you can inspect before copying.

.EXAMPLE
    .\Extract-YcScripts.ps1 -SaveZipOnly
    Just decrypt to a plain .zip.
#>
[CmdletBinding()]
param(
    [string] $Destination = 'C:\',
    [string] $Password,
    [switch] $SaveZipOnly
)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 2.0

# SHA256 of the decrypted zip, so a good password still gets checked against
# the artefact the build actually produced.
$ExpectedZipSha = '22B8F00B53AF207B9AAE36C472D2C9C9391BC0159FF1B028FC8CBD242764F3A7'

function Get-YcPlainPassword {
    param([string] $Supplied)
    if ($Supplied) { return $Supplied }
    $sec = Read-Host -Prompt 'Archive password' -AsSecureString
    $b = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($sec)
    try { return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($b) }
    finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($b) }
}

function Unprotect-YcBlob {
    param([byte[]] $Blob, [string] $Pass)

    if ($Blob.Length -lt 68) { throw 'Payload is truncated.' }
    $magic = [Text.Encoding]::ASCII.GetString($Blob, 0, 4)
    if ($magic -ne 'YCS1') { throw ('Bad payload header "' + $magic + '" - this file is damaged.') }

    $salt = New-Object byte[] 16; [Array]::Copy($Blob, 4,  $salt, 0, 16)
    $iv   = New-Object byte[] 16; [Array]::Copy($Blob, 20, $iv,   0, 16)
    $mac  = New-Object byte[] 32; [Array]::Copy($Blob, 36, $mac,  0, 32)
    $ctLen = $Blob.Length - 68
    $ct   = New-Object byte[] $ctLen; [Array]::Copy($Blob, 68, $ct, 0, $ctLen)

    # PBKDF2-HMAC-SHA1 - the default for Rfc2898DeriveBytes on .NET Framework,
    # which is what PowerShell 5.1 runs on. Do not "upgrade" this to SHA256
    # without changing the builder too; Server 2016 ships .NET 4.6.2 and the
    # SHA256 overload is not there.
    $kdf = New-Object System.Security.Cryptography.Rfc2898DeriveBytes($Pass, $salt, 200000)
    try { $dk = $kdf.GetBytes(64) } finally { $kdf.Dispose() }
    $key = New-Object byte[] 32; [Array]::Copy($dk, 0,  $key, 0, 32)
    $mk  = New-Object byte[] 32; [Array]::Copy($dk, 32, $mk,  0, 32)

    # Verify BEFORE decrypting. A wrong password must fail here, not produce rubbish.
    $signed = New-Object byte[] (36 + $ctLen)
    [Array]::Copy($Blob, 0, $signed, 0, 36)
    [Array]::Copy($ct,   0, $signed, 36, $ctLen)
    $h = New-Object System.Security.Cryptography.HMACSHA256(,$mk)
    try { $calc = $h.ComputeHash($signed) } finally { $h.Dispose() }

    $ok = $true
    for ($i = 0; $i -lt 32; $i++) { if ($calc[$i] -ne $mac[$i]) { $ok = $false } }
    if (-not $ok) { throw 'Wrong password, or the file has been altered in transit.' }

    $aes = New-Object System.Security.Cryptography.AesManaged
    try {
        $aes.KeySize = 256; $aes.BlockSize = 128
        $aes.Mode = [System.Security.Cryptography.CipherMode]::CBC
        $aes.Padding = [System.Security.Cryptography.PaddingMode]::PKCS7
        $aes.Key = $key; $aes.IV = $iv
        $d = $aes.CreateDecryptor()
        try { return $d.TransformFinalBlock($ct, 0, $ct.Length) } finally { $d.Dispose() }
    } finally { $aes.Dispose() }
}

# --- encrypted payload (AES-256-CBC, PBKDF2-HMAC-SHA1 x200000, HMAC-SHA256 authenticated) ---
# Base64. The password is not here.
$YcPayload = @'

'@

$pass = Get-YcPlainPassword -Supplied $Password
Write-Host 'Deriving key (200,000 PBKDF2 rounds, a second or two)...' -ForegroundColor Cyan
$zipBytes = Unprotect-YcBlob -Blob ([Convert]::FromBase64String($YcPayload)) -Pass $pass
$pass = $null

$sha = [BitConverter]::ToString(
    (New-Object System.Security.Cryptography.SHA256Managed).ComputeHash($zipBytes)).Replace('-', '')
if ($sha -ne $ExpectedZipSha) {
    throw ('Decrypted, but the zip does not match the expected build. Got ' + $sha)
}
Write-Host ('Decrypted and verified: ' + $zipBytes.Length + ' bytes, SHA256 matches the build.') -ForegroundColor Green

$zipPath = Join-Path ([System.IO.Path]::GetTempPath()) ('yc-cscripts-' + [guid]::NewGuid().ToString('N').Substring(0,8) + '.zip')
if ($SaveZipOnly) { $zipPath = Join-Path $PSScriptRoot 'yc-cscripts-payload-20260830.zip' }
[IO.File]::WriteAllBytes($zipPath, $zipBytes)

if ($SaveZipOnly) {
    Write-Host ('Wrote ' + $zipPath) -ForegroundColor Green
    Write-Host 'Nothing was extracted (-SaveZipOnly).' -ForegroundColor Yellow
    return
}

try {
    if (-not (Test-Path -LiteralPath $Destination)) { New-Item -ItemType Directory -Path $Destination -Force | Out-Null }
    Write-Host ('Extracting to ' + $Destination + ' ...') -ForegroundColor Cyan
    # -Force overwrites the scripts and leaves everything else in C:\Scripts alone
    # (binaries, virtio\, the .provisioned / .rearm-done markers).
    Expand-Archive -LiteralPath $zipPath -DestinationPath $Destination -Force
    $scripts = Join-Path $Destination 'Scripts'
    $n = @(Get-ChildItem -LiteralPath $scripts -Recurse -File -ErrorAction SilentlyContinue).Count
    Write-Host ('Done. ' + $n + ' files under ' + $scripts) -ForegroundColor Green
    Write-Host ''
    Write-Host 'Check it:' -ForegroundColor Cyan
    Write-Host '    Get-FileHash C:\Scripts\_yc-licensing.ps1 -Algorithm SHA256   # 40963626643C35C9...'
    Write-Host '    licence-report'
    Write-Host '    convert-edition -List'
} finally {
    Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue
}
